/* ЗНАЧОК СОСТОЯНИЯ — пример картинок и объектов плагина.
   Рисует SVG-кружок по числу в клетке (зелёный, жёлтый, красный) и кладёт его
   на лист ОБЪЕКТОМ: при картинке остаются данные (адрес клетки и порог), и по
   двойному щелчку плагин перечитывает клетку и перерисовывает кружок.

   Рисовать SVG плагину можно как угодно: он отдаёт текст, а картинку на лист
   кладёт приложение — страницы у плагина нет. */

/* Поля панели и их умолчания. параметры() зовём В ФУНКЦИИ: на верхнем уровне код
   выполняется один раз, при запуске потока, и запомнил бы только умолчания. */
const ПОЛЯ = ({
  порог: {тип: 'число', имя: 'Порог «хорошо»', умолчание: 100},
  предел: {тип: 'число', имя: 'Порог «плохо»', умолчание: 50},
});

/* Кружок: цвет по значению, подпись — само значение. */
function кружок(значение, порог, предел){
  const цвет = значение >= порог ? '#1a7f37' : значение >= предел ? '#bf8700' : '#c2410c';
  const текст = значение === null ? '—' : String(Math.round(значение));
  return '<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48">'
    + '<circle cx="24" cy="24" r="21" fill="' + цвет + '"/>'
    + '<text x="24" y="30" font-family="system-ui,sans-serif" font-size="15" font-weight="600"'
    + ' fill="#fff" text-anchor="middle">' + текст + '</text></svg>';
}

/* Поставить значок рядом с выделенной клеткой. */
function Поставить(){
  const п = параметры(ПОЛЯ);
  const в = книга.выделение;
  const значение = ячейка(в.адрес).значение;
  if(typeof значение !== 'number')
    throw new Error('В клетке ' + в.адрес + ' нет числа — станьте на число и нажмите снова.');
  const свои = {клетка: в.лист + '!' + в.адрес, порог: п.порог, предел: п.предел};
  const id = картинка.объект(кружок(значение, п.порог, п.предел), свои,
    {адрес: диапазон(в.адрес).адрес, ширина: 48, высота: 48, сдвигX: 4, сдвигY: 2, имя: 'Значок ' + в.адрес});
  сообщить('Значок поставлен у ' + в.адрес + ' (' + id + '). Двойной щелчок по нему — перечитать клетку.');
}

/* Двойной щелчок по значку: перечитать клетку и перерисовать. */
function Обновить(){
  const п2 = книга.повод;
  const свои = JSON.parse(п2.свои);
  const где = свои.клетка.split('!');
  const значение = лист(где[0]).ячейка(где[1]).значение;
  картинка.изменить(п2.id, {данные: кружок(typeof значение === 'number' ? значение : null, свои.порог, свои.предел), свои: свои});
  сообщить('Значок у ' + свои.клетка + ' обновлён: ' + значение);
}

/* Обновить все значки листа разом — по их же данным. */
async function ОбновитьВсе(){
  const все = await картинка.список();
  let сделано = 0;
  for(const к of все){
    if(!к.объект || !к.свои) continue;
    const свои = JSON.parse(к.свои);
    if(!свои.клетка) continue;
    const где = свои.клетка.split('!');
    const значение = лист(где[0]).ячейка(где[1]).значение;
    картинка.изменить(к.id, {данные: кружок(typeof значение === 'number' ? значение : null, свои.порог, свои.предел)});
    сделано++;
  }
  сообщить('Обновлено значков: ' + сделано + ' из ' + все.length + ' картинок листа.');
}
